const CSS="*{box-sizing:border-box}\n.card{display:flex;flex-direction:column;width:100%;height:100%;min-width:0;min-height:0;padding:10px;overflow:hidden;color:var(--ink);background:transparent;font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card[data-size=\"3x3\"]{padding:8px;font-size:11px}\nbutton,input,select,textarea{font:inherit;color:var(--ink)}\nbutton{cursor:pointer}\nbutton:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,.item:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.lv,.dv,.form{display:flex;flex-direction:column;gap:6px;flex:1;min-height:0;min-width:0}\n.dual .short{display:none}\n.card[data-size=\"3x3\"] .dual .full{display:none}\n.card[data-size=\"3x3\"] .dual .short{display:inline}\n.lv-head{display:none;align-items:baseline;gap:8px;flex:none}\n.card[data-size=\"3x6\"] .lv-head,.card[data-size=\"6x6\"] .lv-head{display:flex}\n.lv-title{font-size:15px;font-weight:700}\n.cnt{color:var(--muted);font-size:11px}\n.lv-top{display:flex;align-items:center;gap:6px;min-width:0;flex:none}\n.search{flex:1;min-width:0;height:30px;padding:0 9px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink)}\n.search::placeholder{color:var(--muted)}\n.add{flex:none;height:30px;min-width:30px;padding:0 10px;border:0;border-radius:8px;background:var(--accent);color:var(--on-accent);font-weight:700;white-space:nowrap}\n.seg{display:flex;flex:none;border:1px solid var(--line);border-radius:8px;overflow:hidden}\n.seg button{border:0;background:transparent;height:28px;padding:0 9px;white-space:nowrap}\n.seg button.on{background:var(--accent);color:var(--on-accent);font-weight:600}\n.lv-top .seg{display:none}\n.card[data-size=\"6x3\"] .lv-top .seg,.card[data-size=\"6x6\"] .lv-top .seg{display:flex}\n.sels{display:none;gap:6px;flex:none}\n.card[data-size=\"3x3\"] .sels,.card[data-size=\"3x6\"] .sels{display:flex}\n.sels select{flex:1;min-width:0;height:28px;padding:0 4px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink)}\n.chips{display:none;gap:6px;flex:none;overflow-x:auto;padding-bottom:2px}\n.card[data-size=\"6x3\"] .chips,.card[data-size=\"6x6\"] .chips{display:flex}\n.card[data-size=\"6x6\"] .chips{flex-wrap:wrap;overflow-x:hidden;overflow-y:auto;max-height:62px}\n.chip{flex:none;height:26px;padding:0 10px;border:1px solid var(--line);border-radius:999px;background:transparent;white-space:nowrap}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.chip i{font-style:normal;opacity:.7;margin-left:4px}\n.items{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.item{flex:none;display:flex;flex-direction:column;gap:3px;min-width:0;padding:7px 9px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);cursor:pointer}\n.i-main,.i-ver{min-width:0}\n.i-title{display:flex;align-items:center;gap:6px;min-width:0}\n.badge{flex:none;padding:0 6px;border-radius:6px;background:var(--soft);font-size:11px;line-height:18px}\n.i-name{flex:1;min-width:0;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.i-sub{color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.i-ver{display:flex;flex-direction:column;gap:1px}\n.i-date{display:flex;align-items:center;gap:6px;min-width:0}\n.dt{font-variant-numeric:tabular-nums;white-space:nowrap}\n.i-topic{display:none;color:var(--muted);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tag{flex:none;padding:0 6px;border-radius:6px;background:var(--accent);color:var(--on-accent);font-size:11px;line-height:18px;white-space:nowrap}\n.tag.weak{background:transparent;color:var(--muted);border:1px solid var(--line)}\n.i-loc{color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.i-note{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}\n.card[data-size=\"3x3\"] .i-sub,.card[data-size=\"3x3\"] .i-loc,.card[data-size=\"3x3\"] .i-note{display:none}\n.card[data-size=\"3x3\"] .i-topic{display:block}\n.card[data-size=\"3x3\"] .item{padding:6px 8px;gap:2px}\n.card[data-size=\"6x3\"] .item,.card[data-size=\"6x6\"] .item{display:grid;grid-template-columns:minmax(0,4fr) minmax(0,6fr);gap:2px 12px}\n.card[data-size=\"6x3\"] .i-ver,.card[data-size=\"6x6\"] .i-ver{display:grid;grid-template-columns:auto minmax(0,1fr);gap:1px 8px;align-items:center}\n.card[data-size=\"6x3\"] .i-note,.card[data-size=\"6x6\"] .i-note{grid-column:1/-1;-webkit-line-clamp:1}\n.card[data-size=\"6x6\"] .i-note{-webkit-line-clamp:2}\n.empty{margin:auto;display:flex;flex-direction:column;align-items:center;gap:8px;padding:10px;text-align:center;color:var(--muted)}\n.empty b{color:var(--ink)}\n.card[data-size=\"3x3\"] .empty .sub{display:none}\n.btn{height:32px;padding:0 14px;border:1px solid var(--line);border-radius:8px;background:transparent;white-space:nowrap}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\nbutton:disabled{opacity:.6;cursor:default}\n\n.back{flex:none;width:30px;height:30px;padding:0;border:1px solid var(--line);border-radius:8px;background:transparent;font-size:18px;line-height:1}\n.dv-head,.f-head{display:flex;align-items:center;gap:6px;flex:none;min-width:0}\n.dv-title{flex:1;min-width:0}\n.dv-name{font-weight:700;font-size:14px;line-height:1.25;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}\n.dv-meta{color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.hd-acts{display:flex;gap:6px;flex:none}\n.mini{height:28px;padding:0 9px;border:1px solid var(--line);border-radius:7px;background:transparent;white-space:nowrap}\n.mini.pri{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.top-add{display:none}\n.card[data-size=\"6x3\"] .top-add{display:inline-block}\n.card[data-size=\"6x3\"] .dv-foot,.card[data-size=\"6x3\"] .f-foot{display:none}\n.top-acts{display:none}\n.card[data-size=\"6x3\"] .top-acts{display:flex}\n.hint{flex:none;color:var(--muted);font-size:11px}\n.dv-body,.f-body{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.dv-foot,.f-foot{flex:none;display:flex;gap:6px}\n.dv-foot .btn,.f-foot .btn{flex:1}\n.ver{flex:none;display:flex;flex-direction:column;gap:4px;min-width:0;padding:8px 9px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.ver.cur{border-color:var(--accent);box-shadow:inset 3px 0 0 var(--accent)}\n.v-top{display:flex;align-items:center;gap:6px;flex-wrap:wrap}\n.v-date{font-weight:700;font-variant-numeric:tabular-nums}\n.v-row{display:flex;gap:6px;min-width:0}\n.v-k{flex:none;color:var(--muted)}\n.v-v{flex:1;min-width:0;overflow-wrap:anywhere;user-select:text}\n.v-acts{display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:2px}\n.ask{flex:1 1 100%;font-weight:600}\n.f-title{flex:1;min-width:0;font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.fld{display:flex;flex-direction:column;gap:3px;flex:none;min-width:0}\n.fld>label{color:var(--muted);font-size:11px}\n.fld input[type=text],.fld input[type=date],.fld textarea{width:100%;min-width:0;height:32px;padding:0 9px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink)}\n.fld textarea{height:auto;min-height:60px;padding:6px 9px;resize:vertical}\n.fld .seg{align-self:flex-start;max-width:100%}\n.fld .seg button{height:30px}\n.tchips{display:flex;flex-wrap:wrap;gap:5px;margin-top:2px}\n.tchips .chip{height:24px;padding:0 8px;font-size:11px}\n.sec{flex:none;margin-top:4px;padding-top:6px;border-top:1px solid var(--line);color:var(--muted);font-size:11px;font-weight:600}\n.chk{display:flex;align-items:center;gap:8px;min-height:30px;flex:none}\n.chk input{width:18px;height:18px;margin:0;accent-color:var(--accent)}\n.err{flex:none;padding:6px 8px;border:1px solid var(--ink);border-radius:8px;font-weight:600;overflow-wrap:anywhere}\n.ask-box{display:flex;flex-direction:column;gap:6px;flex:none;padding:8px;border:1px solid var(--ink);border-radius:8px;overflow-wrap:anywhere}\n";
var KINDS=['数据表','图表','文稿'];
var KSHORT={'数据表':'表','图表':'图','文稿':'文'};
var NONE='__none';

function mk(el,tag,attrs,...kids){
  var flat=kids.flat(Infinity).filter(function(k){return k!==null&&k!==undefined&&k!==false;}).map(function(k){return typeof k==='number'?String(k):k;});
  return el(tag,attrs||{},...flat);
}
function dual(el,full,short){
  return mk(el,'span',{class:'dual'},mk(el,'span',{class:'full'},full),mk(el,'span',{class:'short'},short));
}
function btn(el,label,fn,cls){
  return mk(el,'button',{type:'button',class:cls||'mini',onclick:fn},label);
}
function mats(s){return Array.isArray(s&&s.materials)?s.materials:[];}
function withMats(s,list){return Object.assign({},s||{},{materials:list});}
function sortedVers(m){
  return (m.versions||[]).slice().sort(function(a,b){
    if(a.date!==b.date)return a.date<b.date?1:-1;
    return (b.at||0)-(a.at||0);
  });
}
function curVer(m){
  return (m.versions||[]).find(function(v){return v.id===m.currentId;})||null;
}
function shownVer(m){return curVer(m)||sortedVers(m)[0]||null;}
function topicOf(m){return String(m.topic||'').trim();}
function blob(parts){
  return parts.map(function(x){return String(x||'');}).join(' ').toLowerCase();
}
function matchInfo(m,q){
  if(!q)return {hit:true,hist:false};
  var terms=q.split(/\s+/).filter(Boolean);
  var sv=shownVer(m);
  var main=blob([m.name,m.topic,m.kind,sv&&sv.location,sv&&sv.note,sv&&sv.date]);
  var extra=(m.versions||[]).reduce(function(a,v){return a.concat([v.location,v.note,v.date]);},[]);
  var all=main+' '+blob(extra);
  var inMain=terms.every(function(t){return main.indexOf(t)>=0;});
  var inAll=terms.every(function(t){return all.indexOf(t)>=0;});
  return {hit:inAll,hist:inAll&&!inMain};
}
function topicStats(list){
  var map=Object.create(null);
  list.forEach(function(m){var t=topicOf(m)||NONE;map[t]=(map[t]||0)+1;});
  var arr=Object.keys(map).filter(function(k){return k!==NONE;}).sort(function(a,b){
    return map[b]-map[a]||a.localeCompare(b,'zh');
  }).map(function(k){return {key:k,label:k,n:map[k]};});
  if(map[NONE])arr.push({key:NONE,label:'未归类',n:map[NONE]});
  return arr;
}
function cmpRows(a,b){
  var va=shownVer(a.m),vb=shownVer(b.m);
  var da=va?va.date:'',db=vb?vb.date:'';
  if(da!==db)return da<db?1:-1;
  return (b.m.createdAt||0)-(a.m.createdAt||0);
}

async function doCommit(c,fn,nextUi){
  var ui=c.ui;
  if(ui.saving)return false;
  ui.saving=true;
  ui.err='';
  try{
    await c.commit(fn,Object.assign({},ui,nextUi||{},{saving:false,err:''}));
    return true;
  }catch(e){
    ui.saving=false;
    ui.err='保存失败：'+((e&&e.message)?e.message:'请稍后重试');
    c.redraw();
    return false;
  }
}
function needText(c,msg){c.ui.err=msg;c.redraw();return false;}
function clean(x){return String(x||'').trim();}

function saveNewMaterial(c){
  var d=c.ui.draft||{},name=clean(d.name);
  if(!name)return needText(c,'请填写材料名称');
  if(!d.date)return needText(c,'请选择版本日期');
  var mid=c.uid(),vid=c.uid(),now=Date.now();
  var m={id:mid,name:name,kind:d.kind||KINDS[0],topic:clean(d.topic),currentId:d.adopt?vid:null,createdAt:now,
    versions:[{id:vid,date:d.date,location:clean(d.location),note:clean(d.note),at:now}]};
  return doCommit(c,function(s){return withMats(s,mats(s).concat([m]));},
    {view:'detail',sel:mid,draft:null,editMat:null,confirmDel:false});
}
function saveMaterialInfo(c){
  var ui=c.ui,d=ui.draft||{},name=clean(d.name),mid=ui.editMat;
  if(!name)return needText(c,'请填写材料名称');
  var kind=d.kind,topic=clean(d.topic);
  return doCommit(c,function(s){
    return withMats(s,mats(s).map(function(m){
      return m.id===mid?Object.assign({},m,{name:name,kind:kind||m.kind,topic:topic}):m;
    }));
  },{view:'detail',draft:null,editMat:null,confirmDel:false});
}
function removeMaterial(c,mid){
  return doCommit(c,function(s){
    return withMats(s,mats(s).filter(function(m){return m.id!==mid;}));
  },{view:'list',sel:null,draft:null,editMat:null,editVer:null,confirmDel:false,confirmVer:null});
}
function saveVersion(c){
  var ui=c.ui,d=ui.draft||{},mid=ui.sel;
  if(!d.date)return needText(c,'请选择版本日期');
  var vid=ui.editVer||c.uid(),adopt=!!d.adopt,now=Date.now();
  var nv={id:vid,date:d.date,location:clean(d.location),note:clean(d.note)};
  return doCommit(c,function(s){
    return withMats(s,mats(s).map(function(m){
      if(m.id!==mid)return m;
      var list=m.versions||[];
      var exists=list.some(function(x){return x.id===vid;});
      var vs=exists?list.map(function(x){return x.id===vid?Object.assign({},x,nv):x;})
                   :list.concat([Object.assign({at:now},nv)]);
      var cur=m.currentId;
      if(adopt)cur=vid;else if(cur===vid)cur=null;
      return Object.assign({},m,{versions:vs,currentId:cur});
    }));
  },{view:'detail',draft:null,editVer:null,confirmVer:null});
}
function setCurrent(c,mid,vid){
  return doCommit(c,function(s){
    return withMats(s,mats(s).map(function(m){
      return m.id===mid?Object.assign({},m,{currentId:vid}):m;
    }));
  },{});
}
function removeVersion(c,mid,vid){
  return doCommit(c,function(s){
    return withMats(s,mats(s).map(function(m){
      if(m.id!==mid)return m;
      var vs=(m.versions||[]).filter(function(x){return x.id!==vid;});
      if(!vs.length)return m;
      return Object.assign({},m,{versions:vs,currentId:m.currentId===vid?null:m.currentId});
    }));
  },{confirmVer:null});
}

function openAdd(c){
  var ui=c.ui;
  ui.view='matForm';ui.editMat=null;ui.err='';ui.confirmDel=false;
  ui.draft={name:'',kind:ui.kind||KINDS[0],topic:(ui.topic&&ui.topic!==NONE)?ui.topic:'',
    date:c.day(),location:'',note:'',adopt:true};
  c.redraw();
}
function renderItem(c,row){
  var el=c.el,ui=c.ui,m=row.m,v=shownVer(m),cur=curVer(m),topic=topicOf(m);
  var open=function(){ui.view='detail';ui.sel=m.id;ui.err='';ui.confirmVer=null;c.redraw();};
  var sub=(topic||'未归类')+' · '+(m.versions||[]).length+' 个版本'+(row.hist?' · 命中历史版本':'');
  return mk(el,'div',{class:'item',role:'button',tabindex:'0',onclick:open,
      onkeydown:function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}}},
    mk(el,'div',{class:'i-main'},
      mk(el,'div',{class:'i-title'},
        mk(el,'span',{class:'badge'},dual(el,m.kind,KSHORT[m.kind]||m.kind)),
        mk(el,'span',{class:'i-name'},m.name)),
      mk(el,'div',{class:'i-sub'},sub)),
    v?mk(el,'div',{class:'i-ver'},
      mk(el,'div',{class:'i-date'},
        mk(el,'span',{class:cur?'tag':'tag weak'},cur?dual(el,'✓ 当前采用','采用'):dual(el,'最新·未标采用','最新')),
        mk(el,'span',{class:'dt'},v.date),
        mk(el,'span',{class:'i-topic'},topic)),
      mk(el,'div',{class:'i-loc'},v.location||'未记录位置'),
      mk(el,'div',{class:'i-note'},v.note||'未写改动说明')):null);
}
function renderList(c){
  var el=c.el,ui=c.ui,list=mats(c.state);
  var stats=topicStats(list);
  if(ui.topic&&!stats.some(function(t){return t.key===ui.topic;}))ui.topic='';
  var itemsBox=mk(el,'div',{class:'items'});
  var cnt=mk(el,'span',{class:'cnt'},list.length+' 项');
  function fill(){
    while(itemsBox.firstChild)itemsBox.removeChild(itemsBox.firstChild);
    var q=clean(ui.q).toLowerCase(),rows=[];
    list.forEach(function(m){
      var t=topicOf(m)||NONE;
      if(ui.topic&&ui.topic!==t)return;
      if(ui.kind&&ui.kind!==m.kind)return;
      var mi=matchInfo(m,q);
      if(mi.hit)rows.push({m:m,hist:mi.hist});
    });
    rows.sort(cmpRows);
    cnt.textContent=rows.length===list.length?list.length+' 项':rows.length+' / '+list.length+' 项';
    if(!list.length){
      itemsBox.appendChild(mk(el,'div',{class:'empty'},mk(el,'b',{},'还没有登记材料'),
        mk(el,'div',{class:'sub'},'数据表、图表、文稿的名称、存放位置和各版本都记在这里'),
        btn(el,'登记第一份材料',function(){openAdd(c);},'btn primary')));
      return;
    }
    if(!rows.length){
      itemsBox.appendChild(mk(el,'div',{class:'empty'},mk(el,'b',{},'没有符合条件的材料'),
        btn(el,'清除筛选',function(){ui.q='';ui.topic='';ui.kind='';c.redraw();},'btn')));
      return;
    }
    rows.forEach(function(r){itemsBox.appendChild(renderItem(c,r));});
  }
  var search=mk(el,'input',{class:'search',type:'text',placeholder:'查找名称、主题、位置、改动','aria-label':'查找材料',
    oninput:function(e){ui.q=e.target.value;fill();}});
  search.value=ui.q||'';
  var setKind=function(k){return function(){ui.kind=k;c.redraw();};};
  var seg=mk(el,'div',{class:'seg'},['全部'].concat(KINDS).map(function(k,i){
    var val=i?k:'',on=(ui.kind||'')===val;
    return mk(el,'button',{type:'button',class:on?'on':'','aria-pressed':on?'true':'false',onclick:setKind(val)},k);
  }));
  var add=mk(el,'button',{type:'button',class:'add','aria-label':'登记新材料',onclick:function(){openAdd(c);}},dual(el,'＋ 登记','＋'));
  var tsel=mk(el,'select',{'aria-label':'按研究主题筛选',onchange:function(e){ui.topic=e.target.value;c.redraw();}},
    mk(el,'option',{value:''},'全部主题'),
    stats.map(function(t){return mk(el,'option',{value:t.key},t.label+' ('+t.n+')');}));
  tsel.value=ui.topic||'';
  var ksel=mk(el,'select',{'aria-label':'按类型筛选',onchange:function(e){ui.kind=e.target.value;c.redraw();}},
    mk(el,'option',{value:''},'全部类型'),
    KINDS.map(function(k){return mk(el,'option',{value:k},k);}));
  ksel.value=ui.kind||'';
  var chips=mk(el,'div',{class:'chips'},
    [{key:'',label:'全部',n:list.length}].concat(stats).map(function(t){
      var on=(ui.topic||'')===t.key;
      return mk(el,'button',{type:'button',class:on?'chip on':'chip','aria-pressed':on?'true':'false',
        onclick:function(){ui.topic=t.key;c.redraw();}},t.label,mk(el,'i',{},String(t.n)));
    }));
  fill();
  return mk(el,'div',{class:'lv'},
    mk(el,'div',{class:'lv-head'},mk(el,'span',{class:'lv-title'},'研究材料目录'),cnt),
    mk(el,'div',{class:'lv-top'},search,seg,add),
    mk(el,'div',{class:'sels'},tsel,ksel),
    chips,
    itemsBox);
}

function openAddVersion(c,m){
  var ui=c.ui;
  ui.view='verForm';ui.editVer=null;ui.err='';ui.confirmVer=null;
  ui.draft={date:c.day(),location:'',note:'',adopt:false};
